using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer(options =>
{
    options.ServerInfo = new() { Name = "McpWebService", Version = "1.0.0" };
    options.Capabilities = new()
    {
        Tools = new() { ListChanged = true },
        Resources = new() { Subscribe = true, ListChanged = true }
    };
})
.WithHttpTransport()
.WithToolsFromAssembly()
.WithResourcesFromAssembly();

var app = builder.Build();

app.MapMcp();
app.MapGet("/health", () => "ok");

app.Run();

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpWebService.Tools;

[McpServerToolType]
public static class EchoTools
{
    [McpServerTool, Description("Echoes the input message back with a timestamp.")]
    public static string Echo(
        [Description("The message to echo back")] string message)
    {
        return $"[{DateTime.UtcNow:O}] {message}";
    }

    [McpServerTool, Description("Returns the current server time in UTC.")]
    public static string GetServerTime()
    {
        return DateTime.UtcNow.ToString("O");
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpWebService.Resources;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the current application configuration.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            Version = "1.0.0",
            Features = new
            {
                CachingEnabled = true,
                MaxRequestsPerMinute = 100,
                SupportedLocales = new[] { "en-US", "es-ES", "fr-FR" }
            }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/endpoints", Name = "Service Endpoints",
        MimeType = "application/json"),
     Description("Returns configured external service endpoints.")]
    public static string GetEndpoints()
    {
        var endpoints = new
        {
            Api = "https://api.example.com/v2",
            Auth = "https://auth.example.com",
            Storage = "https://storage.example.com"
        };

        return JsonSerializer.Serialize(endpoints, new JsonSerializerOptions { WriteIndented = true });
    }
}

